<?php $title=$definition[0];$description=['products'=>'Catalog overview. Search materials, SKUs, categories and brands.','categories'=>'Organize a clear path through your materials.','brands'=>'Manage the names behind your collections.','inventory'=>'Review stock in each variant’s selling unit.','orders'=>'Search order numbers or customer details and manage fulfillment.','customers'=>'Find customer contact and verification details.','coupons'=>'Manage discounts and usage limits.','enquiries'=>'Store visit leads submitted from product pages.'][$module]??'';require __DIR__.'/header.php';
