<nav class="fallback-pagination" aria-label="Table pages"><?php if($page>1): ?><a class="button secondary" href="?page=<?= $page-1 ?>&amp;q=<?= $e(urlencode(is_string($_GET['q']??null)?$_GET['q']:'')) ?>">Previous</a><?php endif; ?><span>Page <?= $page ?> · <?= $e($result['recordsFiltered']) ?> matches</span><?php if($page*20<$result['recordsFiltered']): ?><a class="button secondary" href="?page=<?= $page+1 ?>&amp;q=<?= $e(urlencode(is_string($_GET['q']??null)?$_GET['q']:'')) ?>">Next</a><?php endif; ?></nav></section>
